class Solution {
  public int[] bestCoordinate(int[][] towers, int radius) {
    int[] best = {0, 0};
    int bestQuality = -1;
    for (int x = 0; x <= 50; x++)
      for (int y = 0; y <= 50; y++) {
        int quality = 0;
        for (int[] t : towers) {
          int dx = x - t[0], dy = y - t[1], d2 = dx * dx + dy * dy;
          if (d2 <= radius * radius) quality += (int) (t[2] / (1 + Math.sqrt(d2)));
        }
        if (quality > bestQuality) {
          bestQuality = quality;
          best[0] = x;
          best[1] = y;
        }
      }
    return best;
  }
}
